        revision = event.get("revision", 0)
        key = (revision, pos) if revision_first else (sequence, revision, pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), mode)
        base = raw if original_tax else net
        tax = rounded(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _build_ledger(revision_first, original_tax):
    return lambda data: _ledger(data, revision_first, original_tax)


def _dependency_solver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    constraints = {name: tuple(bounds) for name, bounds in data["roots"].items()}
    best = None
    best_vector = None

    def cyclic(rows):
        active, done = set(), set()

        def visit(name):
            if name in active:
                return True
            if name in done:
                return False
            active.add(name)
            for dep in rows[name].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                if visit(dep["name"]):
                    return True
            active.remove(name)
            done.add(name)
            return False

        return any(visit(name) for name in rows if name not in done)

    def search(limits, versions, rows):
        nonlocal best, best_vector
        for name, version in versions.items():
            low, high = limits[name]
            if not low <= version <= high:
                return
        unresolved = [name for name in limits if name not in versions]
        if not unresolved:
            if cyclic(rows):
                return
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector, best = vector, dict(versions)
            return

        name = min(unresolved)
        low, high = limits[name]
        candidates = [row for row in packages.get(name, [])
                      if low <= row["version"] <= high
                      and row["version"] not in blocked.get(name, [])
                      and (name not in pins or row["version"] == pins[name])]
        for row in sorted(candidates, key=lambda r: r["version"], reverse=True):
            next_limits = dict(limits)
            next_versions = dict(versions)
            next_rows = dict(rows)
            version = row["version"]
            next_versions[name] = version
            next_rows[name] = row
            valid = True
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                dep_name = dep["name"]
                lo, hi = dep["min"], dep["max"]
                if dep_name in next_limits:
                    lo = max(lo, next_limits[dep_name][0])
                    hi = min(hi, next_limits[dep_name][1])
                if lo > hi:
                    valid = False
                    break
                next_limits[dep_name] = (lo, hi)
                if dep_name in next_versions and not lo <= next_versions[dep_name] <= hi:
                    valid = False
                    break
            if valid:
                search(next_limits, next_versions, next_rows)

    search(constraints, {}, {})
    return {"error": "unsatisfiable"} if best is None else {"versions": best}


def _schedule(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None
    n = len(jobs)

    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        chosen = [jobs[i] for i in range(n) if mask >> i & 1]
        ids = {job["id"] for job in chosen}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not lo <= counts.get(group, 0) <= hi
               for group, (lo, hi) in quotas.items()):
            continue
        points = []
        for job in chosen:
            points.append((job["start"], 1))
            points.append((job["end"], -1))
        active = 0
        feasible = True
        for _, change in sorted(points):
            active += change
            if active > 2:
                feasible = False
                break
        if not feasible:
            continue
        selected = sorted(ids)
        value = sum(job["value"] for job in chosen)
        if (best_value is None or value > best_value
                or (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    import heapq

    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit_for.get(data["source"], 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = data["start"]
    initial = (data["source"], initial_mask, data["coupons"])
    distances = {initial: start}
    queue = [(start, data["source"], initial_mask, data["coupons"])]
    while queue:
        arrival, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], coupons)]
            if coupons:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)), coupons - 1))
            for duration, left in options:
                reached = depart + duration
                if reached > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, left)
                if reached < distances.get(next_state, float("inf")):
                    distances[next_state] = reached
                    heapq.heappush(queue, (reached, next_node, next_mask, left))
    return {"arrival": None}


